-- ===== Hand-written: constraints Prisma cannot express (docs/modelo-datos.sql) =====

-- D01: at most one policy version in force per category and destination.
CREATE UNIQUE INDEX "ux_politica_vigente"
  ON "politica_gasto" ("id_categoria", "id_destino") WHERE "vigente_hasta" IS NULL;

-- At most one selected quote per travel request.
CREATE UNIQUE INDEX "ux_cotizacion_seleccionada"
  ON "cotizacion" ("id_solicitud") WHERE "seleccionada";

-- S07: the same fiscal key cannot be reported twice while the expense is active.
CREATE UNIQUE INDEX "ux_gasto_clave_fiscal"
  ON "gasto" ("cuit_proveedor", "tipo_comprobante", "punto_venta", "numero_comprobante")
  WHERE "activo" AND "cuit_proveedor" IS NOT NULL AND "numero_comprobante" IS NOT NULL;

ALTER TABLE "solicitud_viaje"
  ADD CONSTRAINT "solicitud_viaje_fechas_check" CHECK ("fecha_fin" >= "fecha_inicio");

ALTER TABLE "verificacion_comprobante"
  ADD CONSTRAINT "verificacion_comprobante_puntaje_check" CHECK ("puntaje" BETWEEN 0 AND 100);
